"""Maintain bounded actual-source provenance for the Linux capstone successor."""
import hashlib,json,pathlib,urllib.request
ROOT=pathlib.Path(__file__).resolve().parents[4];HERE=pathlib.Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def put(p,d):p.write_text(json.dumps(d,indent=2)+'\n',encoding='utf8')
def main():
    captures=ROOT/'build/capstone-linux-sources';captures.mkdir(parents=True,exist_ok=True);resources=[]
    data=[('EPOLL','epoll.7','man7',['T24'],['Level-triggered and edge-triggered: nonblocking drains and ready-list obligations','Questions and answers: descriptor/open-file-description registration and duplicate close','Possible pitfalls: starvation and cached-event lifetime']),('WRITE','write.2','man2',['T23','T21'],['DESCRIPTION and RETURN VALUE: accepted prefixes and short writes','ERRORS: EAGAIN, EINTR, EIO and EPIPE','NOTES: successful write is not a durability guarantee']),('CTL','epoll_ctl.2','man2',['T24','T32'],['DESCRIPTION: ADD, MOD, DEL, saved event data and HUP outstanding data','ERRORS: registration refusal, missing registration and regular-file EPERM'])]
    for name,page,section,domains,locators in data:
        url='https://man7.org/linux/man-pages/'+section+'/'+page+'.html';capture=captures/(page+'.html')
        if not capture.exists():capture.write_bytes(urllib.request.urlopen(url,timeout=30).read())
        resources.append(dict(id='R-CAPL-'+name,title='Linux '+page+' selected capstone boundaries',authors=['Linux man-pages project'],edition='Linux man-pages6.19 HTML rendered2026-09-09',year=2026,kind='manual',url=url,access='Primary HTML passages actually read',domains=domains,role='primary',reason='Resolve concrete service lifecycle and external-effect assumptions',prerequisites=['P3 framed protocol','P5 actual lifecycle and queue'],locators=locators,assignable=True,inspection=dict(date='2026-10-18',method='Direct primary web passage reading, then private exact-byte capture',scope='; '.join(locators),passages=locators,capture=dict(path=capture.relative_to(ROOT).as_posix(),sha256=sha(capture)),limits='Linux interface documentation, not an ISO C rule or proof of arbitrary kernel schedules.')))
    files=['curriculum/guides/integrations.md','curriculum/v5/expansion/legacy_assessments/capstone-contract.md','fixtures/legacy_capstones/boundaries.json','fixtures/integration/pressure.json','labs/checkpoint_depth/include/checkpoint_depth.h','assessor/checkpoint_depth/checkpoint_depth.c','labs/checkpoint_linux_followthrough/bridge.h','labs/checkpoint_linux_followthrough/CONTRACTS.md','assessor/checkpoint_linux_followthrough/bridge.c','labs/ownership/include/ownership.h','labs/ownership/CONTRACTS.md','assessor/ownership/ownership.c','labs/errors/include/errors.h','labs/errors/CONTRACTS.md','assessor/errors/errors.c','labs/coroutines/include/coroutines.h','assessor/coroutines/coroutines.c','assessor/checkpoint_depth/targets/cortex_start.S','assessor/checkpoint_depth/targets/cortex_guest.c','assessor/checkpoint_depth/targets/byte_helpers.c','assessor/checkpoint_depth/targets/arm_helpers.c']
    files += [f'curriculum/projects/PR-CAP-LINUX-{i:02}.md' for i in range(1,5)]+[f'curriculum/v5/expansion/legacy_assessments/PR-CAP-LINUX-{i:02}.json' for i in range(1,5)]
    put(HERE/'resources.json',dict(resources=resources));put(HERE/'source_access.json',dict(source_sha256={n:sha(ROOT/n) for n in files},scope='Actual complete capstone tasks, P3/P5 producer APIs/implementation and selected modern operation bodies; see sources.md for exact limits.',limits=['The coro source inspection concerns COAsync read/poll/cancel and public declarations, not every coroutine project.','Ownership inspection covers scope/shared operations and their declared contract, not independent acceptance.','Original source cards may receive additive publication metadata; historical criteria/baselines are preserved by the closer.']))
    put(HERE/'research_gate.json',dict(status='passage-inspected',scope='Linux capstone authoring support; not independent acceptance',resource_ids=[r['id'] for r in resources],research_input_sha256={p.relative_to(ROOT).as_posix():sha(p) for p in [HERE/'resources.json',HERE/'sources.md',HERE/'source_access.json']},limitations=['Exact final C17/C23 texts remain unavailable; active compiler C17 mode is not final-standard inspection.','Real hardware, seven-day learner performance and external curriculum acceptance are not claimed.']))
if __name__=='__main__':main()
